// Some portions generated by Claude
export type FixtureNodeType = {
  id: string;
  label: string;
};

export type FixtureNode = {
  id: string;
  label: string;
  kind: "iri" | "literal" | "blank";
  types?: FixtureNodeType[];
  datatype?: string;
  language?: string;
  x: number;
  y: number;
};

export type FixtureEdge = {
  id: string;
  source: string;
  predicate: string;
  label: string;
  target: string;
  batchId: string;
};

export type FixtureGraph = {
  nodes: FixtureNode[];
  edges: FixtureEdge[];
  revision: number;
};

export const STAR_STRESS_ROOT_ID = "https://example.org/graph-field/stress/root";
export const STAR_STRESS_BATCH_ID = "star-300-stress-test";

const FIXTURE_CENTER = { x: 640, y: 390 };
const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
const FIRST_LEAF_RADIUS = 210;
const LEAF_RADIAL_STEP = 92;

function paddedIndex(index: number) {
  return String(index).padStart(3, "0");
}

export function createStarStressGraph(
  leafCount = 300,
  revision = 1,
): FixtureGraph {
  const safeLeafCount = Math.max(0, Math.floor(leafCount));
  const rootType = {
    id: "https://example.org/graph-field/type/stress-root",
    label: "Stress-test root",
  };
  const leafTypes = Array.from({ length: 6 }, (_, index) => ({
    id: `https://example.org/graph-field/type/segment-${index + 1}`,
    label: `Leaf segment ${index + 1}`,
  }));
  const nodes: FixtureNode[] = [
    {
      id: STAR_STRESS_ROOT_ID,
      label: `${safeLeafCount}-node fan-out root`,
      kind: "iri",
      types: [rootType],
      ...FIXTURE_CENTER,
    },
  ];
  const edges: FixtureEdge[] = [];

  for (let leafIndex = 1; leafIndex <= safeLeafCount; leafIndex += 1) {
    const zeroBasedIndex = leafIndex - 1;
    const suffix = paddedIndex(leafIndex);
    const angle = zeroBasedIndex * GOLDEN_ANGLE;
    const radius =
      FIRST_LEAF_RADIUS + LEAF_RADIAL_STEP * Math.sqrt(zeroBasedIndex);
    const position = {
      x: FIXTURE_CENTER.x + Math.cos(angle) * radius,
      y: FIXTURE_CENTER.y + Math.sin(angle) * radius,
    };
    let node: FixtureNode;
    if (leafIndex % 12 === 0) {
      node = {
        id: `_:stress-${suffix}`,
        label: `Blank node ${suffix}`,
        kind: "blank",
        ...position,
      };
    } else if (leafIndex % 4 === 0) {
      const literalVariant = Math.floor(leafIndex / 4) % 5;
      if (literalVariant === 0) {
        node = {
          id: `stress-en-${suffix}`,
          label: `English note ${suffix}`,
          kind: "literal",
          language: "en",
          ...position,
        };
      } else if (literalVariant === 1) {
        node = {
          id: `stress-nb-${suffix}`,
          label: `Norsk merknad ${suffix}`,
          kind: "literal",
          language: "nb",
          ...position,
        };
      } else if (literalVariant === 2) {
        node = {
          id: `stress-integer-${suffix}`,
          label: String(leafIndex),
          kind: "literal",
          datatype: "http://www.w3.org/2001/XMLSchema#integer",
          ...position,
        };
      } else if (literalVariant === 3) {
        node = {
          id: `stress-date-${suffix}`,
          label: `2026-07-${String((leafIndex % 28) + 1).padStart(2, "0")}`,
          kind: "literal",
          datatype: "http://www.w3.org/2001/XMLSchema#date",
          ...position,
        };
      } else {
        node = {
          id: `stress-string-${suffix}`,
          label: `Plain string ${suffix}`,
          kind: "literal",
          ...position,
        };
      }
    } else {
      node = {
        id: `https://example.org/graph-field/stress/node/${suffix}`,
        label: `Attached IRI ${suffix}`,
        kind: "iri",
        types: [leafTypes[zeroBasedIndex % leafTypes.length]],
        ...position,
      };
    }
    nodes.push(node);
    edges.push({
      id: `stress-edge-${suffix}`,
      source: STAR_STRESS_ROOT_ID,
      predicate: "https://example.org/graph-field/predicate/attached",
      label: "attached",
      target: node.id,
      batchId: STAR_STRESS_BATCH_ID,
    });
  }

  return { nodes, edges, revision };
}

/** Deterministic cyclic/branching scale fixture with no external metadata dependencies. */
export function createLargeStressGraph(count=50000,revision=1):FixtureGraph {
  const size=Math.max(1,Math.min(100000,Math.floor(count))),columns=Math.ceil(Math.sqrt(size*0.38));
  const nodes:FixtureNode[]=Array.from({length:size},(_,i)=>({id:`urn:graph-field:stress:${i}`,label:`Resource ${i+1}`,kind:"iri",types:[],x:(i%columns)*260,y:Math.floor(i/columns)*90}));
  const edges:FixtureEdge[]=nodes.map((node,i)=>({id:`large-${i}`,source:node.id,target:nodes[(i+(i%5===0?columns:1))%size].id,predicate:"urn:graph-field:stress:relatedTo",label:"related to",batchId:"large-stress"}));
  return {nodes,edges,revision};
}
